volatile int probe_salt;
struct Pair { int low; int high; };
typedef int (*ProbeCallback)(int, int, int, int);
extern int __cdecl write(int, const void *, unsigned);

int probe_three(int a, int b, int c)
{
    return a + b * 3 + c * 5 + probe_salt;
}

int probe_four(int a, int b, int c, int d)
{
    return a + b * 3 + c * 5 + d * 7 + probe_salt;
}

int probe_five(int a, int b, int c, int d, int e)
{
    return a + b * 3 + c * 5 + d * 7 + e * 11 + probe_salt;
}

struct Pair probe_pair(int a, int b, int c, int d)
{
    struct Pair value;
    value.low = a + b;
    value.high = c + d;
    return value;
}

int probe_callback(ProbeCallback callback, int value)
{
    return callback(value, value + 1, value + 2, value + 3);
}

int probe_cdecl(void)
{
    return write(1, "abi\n", 4);
}

int main(void)
{
    struct Pair value;
    int result;
    result = probe_three(1, 2, 3);
    result += probe_four(4, 5, 6, 7);
    result += probe_five(8, 9, 10, 11, 12);
    value = probe_pair(13, 14, 15, 16);
    result += value.low + value.high;
    result += probe_callback(probe_four, 17);
    return result + probe_cdecl();
}
